const locked=async fn=>navigator.locks? navigator.locks.request('chmltech:WMS_demo:ui',fn):fn();
async function refreshShared(){
 sharedInfo=await api('status');account.observe(sharedInfo);setPhoneAddress(sharedInfo.phoneAddress||'');
 if(!sharedInfo.user){sharedReady=false;loadError='Sign in with the account control at the top right.';render();return;}
 loadError='';
 const result=await api('workspace');
 if(!result.state){migration='initialize';sharedReady=false;render();return;}
 // Browser demo never imports a shared or legacy warehouse.
 validateState(result.state);state=result.state;sharedReady=true;migration=null;loadError='';render();
}
async function run(command,payload={},next){
 if(sharedInfo?.user&&!commandRoleAllowed(command,sharedInfo.user.role))throw Error(translate('Your role cannot perform this action.'));
 if(!sharedReady)throw Error('Choose your shared workspace using the banner above, or sign in first.');
 if(upgradeNeeded())throw Error(versionUpdateMessage(sharedInfo));
 return locked(async()=>{
  try{const result=await api('command',{command,payload,revision:state.revision});state=result.state;$('#modal').close();if(next)location.hash=typeof next==='function'?next(result.resultId):next;render();toast(state.events[0].type);return result;}
  catch(error){if(error.status===409)await refreshShared();throw error;}
 });
}
const filtered=rows=>rows.filter(r=>!query||matchesText(JSON.stringify(r),query));
const toolbar=(placeholder,filters=['All'])=>`<div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="${e(placeholder)}" aria-label="${e(placeholder)}" value="${e(query)}"></label><div class="filters">${filters.map(f=>`<button class="filter ${f===filter?'active':''}" data-filter="${e(f)}" aria-pressed="${f===filter}">${e(f)}</button>`).join('')}</div></div>`;
