function itemDetail(id){
  const i=itemById(state,id),t=totals(state,id),rows=state.stock.filter(r=>r.itemId===id);
  return pageHead(i.name,`${i.sku} · ${i.category} · Stock unit: ${i.uom}`,nav('Inventory','inventory','back')+btn('Edit text','edit-item','','',id)+btn('Purchases','purchases','','',id)+btn('Receive stock','receive','down','primary',id))+`<div class="stats">${stat('On hand',t.onHand,`${e(i.uom)} across all locations`,'box')}${stat('Allocated',t.allocated,'Demand from active orders','orders')}${stat('Reserved',t.committed,'Committed to active picks','pick')}${stat('Available',t.available,`Reorder point: ${i.reorderPoint} ${e(i.uom)}`,'layers',true)}</div><section class="card">${cardHead('Product details')}<div class="detail-grid"><div><label>Preferred supplier</label><strong>${e(i.supplier||'—')}</strong></div><div><label>Product description</label><strong style="white-space:pre-wrap;overflow-wrap:anywhere">${e(i.description||'—')}</strong></div></div></section><section class="card">${cardHead('Stock by location','Move free stock or record a count against a location and lot.')} ${rows.length?table(['Location','Lot','>On hand','>Reserved','>Free to move','Actions'],rows.map(r=>{const l=locationById(state,r.locationId);return `<tr><td><strong class="mono">${e(l.code)}</strong><div class="item-sku">${e(l.name)} · ${e(l.type)}</div></td><td class="mono">${e(r.lot)}</td><td class="num">${n(r.qty)}</td><td class="num">${n(r.committed)}</td><td class="num">${n(r.qty-r.committed)}</td><td><div class="actions">${r.qty>r.committed?btn('Move','move','arrow','tiny',r.id):''}${btn('Count','count','check','tiny',r.id)}</div></td></tr>`;})):empty('No stock yet','Receive a delivery to add stock at a warehouse location.',btn('Receive stock','receive','down','primary',id))}</section><div class="hint" style="margin-top:20px">Pickable now: <strong>${n(t.pickable)} ${e(i.uom)}</strong>. Quality hold and staging cannot supply a new pick. Receiving stock becomes pickable after it moves into storage.</div>`;
}
function picking(){
  const rows=filtered(state.picks.map(p=>({...p,customer:orderById(state,p.orderId).customer,orderNumber:orderById(state,p.orderId).number}))).filter(p=>orderById(state,p.orderId).status!=='Cancelled'&&(filter==='All'||p.status===(filter==='Reserved'?'Committed':filter))).reverse();
  return pageHead('Picking','Reserve stock at its source, then move it to outbound staging.',nav('Sales orders','orders','orders'))+`<section class="card">${toolbar('Search pick, order, or customer',['All','Entered','Reserved','Finished'])}${rows.length?table(['Pick','Order / customer','>Qty','Status',''],rows.map(p=>{const o=orderById(state,p.orderId);return `<tr><td><a class="link mono" href="#picking/${p.id}">${e(p.number)}</a></td><td>${e(o.number)}<div class="item-sku">${e(o.customer)}</div></td><td class="num">${n(pickLines(state,p).reduce((n,l)=>n+l.qty,0))}</td><td>${badge(p.status)}</td><td class="num">${nav('Open pick',`picking/${p.id}`,'arrow','tiny')}</td></tr>`;})):empty('No picks in this view','Issue a sales order to create a pick.',nav('Sales orders','orders','orders','primary'))}</section>`;
}
function pickDetail(id){
  const p=pickById(state,id),o=orderById(state,p.orderId),short=p.status==='Entered'?shortages(state,o):[];
  let actions='',desc='';
  if(p.status==='Entered'&&o.status!=='Cancelled'){desc='Reserve all order lines from pickable stock. On-hand quantity will stay the same.';actions=btn('Reserve stock','reserve','pick','primary full',id);}
  if(p.status==='Committed'){desc='Move the reserved quantities below to SHIP-01. Finishing creates the shipment.';actions=btn('Finish pick','finish','check','primary full',id)+btn('Reverse pick','reverse-pick','rotate','full',id);}
  if(p.status==='Finished'){desc='Stock is staged. Continue to shipping, or reverse the pick after reversing any packing or shipment.';actions=nav('Open shipment',`shipping/${p.shipmentId}`,'truck','primary full')+btn('Reverse pick','reverse-pick','rotate','full',id);}
  return pageHead(p.number,`${o.number} · ${o.customer}`,nav('All picks','picking','back'))+(short.length?`<div class="alert"><strong>More stock is needed.</strong> ${short.map(r=>`${e(r.item.sku)} is short ${r.short} ${e(r.item.uom)}`).join('; ')}. Receive stock or move it into storage before reserving.</div>`:'')+`<div class="split"><div><section class="card">${cardHead('Pick lines',p.status==='Entered'?'Stock is assigned when you reserve this pick.':'Follow these source and lot assignments.',badge(p.status))}${table(['Item','>Required','>Pickable now'],pickLines(state,p).map(l=>{const i=itemById(state,l.itemId);return `<tr><td>${itemCell(i)}</td><td class="num">${n(l.qty)} ${e(i.uom)}</td><td class="num">${n(totals(state,i.id).pickable)}</td></tr>`;}))}${p.allocations.length?`<div class="card-head"><h3>Stock assignments</h3></div>${p.allocations.map(a=>{const src=state.stock.find(s=>s.id===a.sourceStockId),i=itemById(state,a.itemId);return `<div class="allocation"><div><strong>${e(i.sku)}</strong><small>${e(locationById(state,src.locationId).code)} ${p.status==='Finished'?'→ SHIP-01':''} · ${e(a.lot)}</small></div><strong>${n(a.qty)} ${e(i.uom)}</strong></div>`;}).join('')}`:''}</section></div><aside class="card">${cardHead('Next action')}<div class="detail-actions"><p>${desc||'The related order has been cancelled.'}</p>${actions}${nav('View sales order',`orders/${o.id}`,'orders','ghost full')}</div></aside></div>`;
}
function shipping(){
  const rows=filtered(state.shipments.map(s=>({...s,customer:orderById(state,s.orderId).customer}))).filter(s=>filter==='All'||s.status===filter).reverse();
  return pageHead('Shipping','Pack staged stock and dispatch it with a complete history.',nav('Picking','picking','pick'))+`<section class="card">${toolbar('Search shipment or customer',['All','Entered','Packed','Shipped','Cancelled'])}${rows.length?table(['Shipment','Customer','Carrier / tracking','Status',''],rows.map(s=>`<tr><td><a href="#shipping/${s.id}" class="link mono">${e(s.number)}</a><div class="item-sku">${e(orderById(state,s.orderId).number)}</div></td><td>${e(s.customer)}</td><td>${e(s.carrier||'Not assigned')}<div class="item-sku">${e(s.tracking||'—')}</div></td><td>${badge(s.status)}</td><td class="num">${nav('Open',`shipping/${s.id}`,'arrow','tiny')}</td></tr>`)):empty('Your next shipment starts with a pick','Finish a reserved pick to create a shipment here.',nav('Open picking','picking','pick','primary'))}</section>`;
}
function shipmentDetail(id){
  const sh=state.shipments.find(s=>s.id===id);if(!sh)throw Error('Shipment not found.');const o=orderById(state,sh.orderId),p=pickById(state,sh.pickId);
  let actions='',desc='';
  if(sh.status==='Entered'){desc='Add packing details, then dispatch. Packing leaves stock unchanged; shipping consumes it.';actions=btn('Pack shipment','pack','box','primary full',id);}
  if(sh.status==='Packed'){desc='Verify the packed order, then mark it shipped. This reduces on-hand stock and releases the reservation.';actions=btn('Ship order','ship','truck','primary full',id)+btn('Reverse packing','reverse-shipment','rotate','full',id);}
  if(sh.status==='Shipped'){desc='Stock has left the warehouse. Reverse this shipment to restore it to staging with its reservation.';actions=btn('Reverse shipment','reverse-shipment','rotate','full',id);}
  if(sh.status==='Cancelled')desc='This shipment was cancelled when its pick was reversed. Its record remains in the history.';
  return pageHead(sh.number,`${o.number} · ${o.customer}`,nav('All shipments','shipping','back'))+`<div class="split"><div><section class="card">${cardHead('Shipment details','',badge(sh.status))}<div class="detail-grid"><div><label>Carrier</label><strong>${e(sh.carrier||'Not assigned')}</strong></div><div><label>Tracking reference</label><strong>${e(sh.tracking||'—')}</strong></div><div><label>Dispatched</label><strong>${sh.shippedAt?e(date(sh.shippedAt)):'Awaiting dispatch'}</strong></div></div>${table(['Item','>Quantity'],deliveryLines(state,sh).map(l=>{const i=itemById(state,l.itemId);return `<tr><td>${itemCell(i)}</td><td class="num">${n(l.qty)} ${e(i.uom)}</td></tr>`;}))}</section><div class="hint" style="margin-top:20px">${sh.status==='Shipped'?'Shipment completed. Reversal will restore both stock and its commitment.':'Stock stays on hand and reserved in SHIP-01 until dispatch.'}</div></div><aside class="card">${cardHead('Next action')}<div class="detail-actions"><p>${desc}</p>${actions}${nav('View pick',`picking/${p.id}`,'pick','ghost full')}${nav('View order',`orders/${o.id}`,'orders','ghost full')}</div></aside></div>`;
}
function locations(){return pageHead('Locations','A place for every item, with clear rules for what can be picked.',btn('New location','new-location','plus','primary'))+`<div class="locations-grid">${state.locations.map(l=>{const rows=state.stock.filter(r=>r.locationId===l.id);return `<section class="location-card"><div class="location-top"><span class="location-icon">${icon('location')}</span>${badge(l.type)}</div><h2>${e(l.code)}</h2><p>${e(l.name)}</p><div class="location-stats"><div><strong>${n(rows.reduce((s,r)=>s+r.qty,0))}</strong><small>On hand</small></div><div><strong>${new Set(rows.filter(r=>r.qty>0).map(r=>r.itemId)).size}</strong><small>SKUs</small></div><div><strong>${n(rows.reduce((s,r)=>s+r.committed,0))}</strong><small>Reserved</small></div></div><div class="legend"><span>${icon(l.pickable?'check':'x')}${l.pickable?'Pickable':'Not pickable'}</span></div>${btn('View stock','location-stock','arrow','tiny',l.id)}</section>`;}).join('')}</div>`;}
function activity(){
  const rows=filtered(state.events);
  return pageHead('Activity','Every inventory change leaves a trail.',btn('Download demo data','export','down'))+`<section class="card">${toolbar('Search action, reference, or note')}<div class="event-list">${rows.length?rows.map(ev=>`<article class="event"><time>${e(date(ev.time))}<br><span class="mono">${e(ev.id)}</span></time><div><h3>${e(ev.type)} <span class="badge">${e(ev.reference)}</span></h3><p>${e(ev.message)}</p>${ev.changes.map(c=>`<div class="delta"><span>${e(itemById(state,c.itemId).sku)} · ${e(locationById(state,c.locationId).code)} · ${e(c.lot)}</span><span class="${c.onHand<0?'negative':'positive'}">On hand ${c.onHand>0?'+':''}${c.onHand}</span><span>Reserved ${c.committed>0?'+':''}${c.committed}</span></div>`).join('')}</div></article>`).join(''):empty('No matching activity','Try another search.')}</div><div class="card-foot"><span>${rows.length} events · Latest 1,000 retained</span><span>Local activity history</span></div></section>`;
}
function render(){
  const [view='dashboards',id]=(location.hash.slice(1)||'dashboards/sales').split('/');
  if(route!==location.hash){if(viewMode!=='classic'||route.slice(1).split('/')[0]!==view){query='';filter='All';}recordTab='General';selectedStock='';route=location.hash;}
  shell(view);
  if(!sharedInfo?.user){$('#main').innerHTML=`<section class="account-gate"><h1>${e(navigationContext(location.hash).module?.label||'Workspace')}</h1><p>${sharedInfo?(sessionExpired?'Your session expired. Sign in again to continue.':'Sign in to the shared workspace.'):'Connecting to Chmltech WMS…'}</p>${sharedInfo?'<button type="button" data-account-action="signin">Sign in</button>':''}</section>`;return;}
  try{let content=viewMode==='classic'&&['inventory','orders','picking','shipping'].includes(view)?classicView(state,view,id,{query,filter,tab:recordTab,stockId:selectedStock}):({dashboards:()=>sharedReady?dashboardView(state,id,sharedInfo?.user?.username||'Local owner'):'<div class="page-head"><div><h1>Dashboards</h1><p>Loading shared dashboard records. Choose shared records or sign in if prompted above.</p></div></div>',overview,business:()=>businessView(state,id,location.hash.split('/')[2]),inventory:()=>id?itemDetail(id):inventory(),suppliers:()=>supplierView(state,id,{query,filter}),purchasing:()=>purchasingView(state,id,{query,filter}),orders:()=>id?orderDetail(id):orders(),picking:()=>id?pickDetail(id):picking(),shipping:()=>id?shipmentDetail(id):shipping(),locations,activity}[view]||overview)();$('#main').innerHTML=versionNoticeHTML(sharedInfo)+(loadError?`<div class="alert">${e(loadError)} ${btn('Data & settings','settings','','tiny')}</div>`:'')+(migration?`<div class="migration-banner"><strong>${migration==='initialize'?'Move your records into shared storage':'A saved browser workspace was found'}</strong><p>${migration==='initialize'?`This browser contains ${state.items.length} products and ${state.operations?.purchases?.length||0} purchase orders. A preserved copy will be kept.`:`Shared storage contains ${state.operations?.purchases?.length||0} POs. Your browser copy contains ${legacyState?.operations?.purchases?.length||0}. Both can be preserved; choose which workspace to use.`}</p>${btn(migration==='initialize'?'Use these records':'Use shared records','shared-use','','primary')}${migration==='compare'?btn('Review browser replacement','shared-replace'):''}</div>`:'')+content;}catch(err){$('#main').innerHTML=empty('This record is unavailable',err.message,nav('Return to overview','overview','back','primary'));}
 applyRoleControls($('#main'),sharedInfo?.user?.role);
 if(view==='business'&&id==='quickbooks')mountQuickBooks();mountReconciliation(state);
}
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${e(label)}<input name="${name}" type="${type}" value="${e(value)}" ${dateInputBounds(type)} ${extra}></label>`;
const select=(label,name,options,value='')=>`<label class="field">${e(label)}<select name="${name}" aria-label="${e(label)}" required>${options.map(o=>`<option value="${e(o[0])}"${o[0]===value?' selected':''}>${e(o[1])}</option>`).join('')}</select></label>`;
const itemOptions=()=>state.items.map(i=>[i.id,`${i.sku} — ${i.name}`]);
const locOptions=(pred=()=>true)=>state.locations.filter(pred).map(l=>[l.id,`${l.code} — ${l.name}`]);
let modalSubmit=null;
function showModal(title,body,submitLabel='',onSubmit=null){
  title=wording(title);submitLabel=wording(submitLabel);
  modalSubmit=onSubmit;const d=$('#modal');d.innerHTML=`<form id="modal-form"><div class="modal-head"><h2 id="modal-title">${e(title)}</h2>${languageControlHTML({id:"modal-interface-language"})}<button type="button" class="icon-btn" data-action="close" aria-label="Close dialog">${icon('x')}</button></div><div class="modal-body">${body}<div class="form-error" id="form-error" role="alert"></div></div><div class="modal-actions"><button type="button" class="btn" data-action="close">${submitLabel?'Cancel':'Done'}</button>${submitLabel?`<button type="submit" class="btn primary">${e(submitLabel)}</button>`:''}</div></form>`;for(const input of d.querySelectorAll("[maxlength]")){input.dataset.maxCharacters=input.getAttribute("maxlength");input.removeAttribute("maxlength");}applyRoleControls(d,sharedInfo?.user?.role);if(!d.open)d.showModal();
}
function confirm(title,text,command,payload,next){showModal(title,`<p>${e(text)}</p>`,title,()=>run(command,payload,next));}
function lineHtml(){return `<div class="order-line"><select name="lineItem" aria-label="Order item">${itemOptions().map(([id,name])=>`<option value="${id}">${e(name)}</option>`).join('')}</select><input name="lineQty" type="number" min="1" step="1" max="10000000" value="1" required aria-label="Order quantity"><button type="button" data-action="remove-line" class="icon-btn" aria-label="Remove line">${icon('x')}</button></div>`;}
const download=(filename,text,type='application/json')=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=filename;a.hidden=true;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},30000);};
async function replaceState(newState){
 validateState(newState);if(!sharedReady)throw Error('Connect to the shared workspace first.');
 const result=await api('replace',{state:newState,revision:state.revision});state=result.state;loadError='';$('#modal').close();render();toast('Shared workspace restored. Previous data was backed up.');
}
async function action(name,id,el){
  if(name==='biz-login'){account.open();return;}
  if(name.startsWith('qbo-')&&(!sharedReady||upgradeNeeded()))throw Error('Connect to the current shared Chmltech WMS server before using QuickBooks.');
  if(await documentScanAction(name,id,el,{s:state,showModal,field}))return;
  if(await deliveryAction(name,id,el,{s:state,run,showModal,field,select}))return;
  if(await planningAction(name,id,el,{s:state,run,showModal,field,select,download,refreshView:render}))return;
  if(await dashboardAction(name,id,el,{s:state,run,showModal,field,select,download,refreshView:render,refreshShared}))return;
  if(await reconciliationAction(name,id,el,{s:state,showModal,field,select,download,refreshShared}))return;
  if(await qboAction(name,id,el,{s:state,showModal,field,select,download,refreshShared}))return;
  if(await insightAction(name,id,el,{s:state,run,showModal,field,select,download,refreshView:render}))return;
  if(await valuationAction(name,id,el,{s:state,run,showModal,field,select,download,refreshView:render}))return;
  if(await costingAction(name,id,el,{s:state,run,showModal,field,select,download,refreshView:render}))return;
  if(await billingAction(name,id,el,{s:state,run,showModal,field,select,download,refreshView:render}))return;
  if(await businessAction(name,id,el,{s:state,run,showModal,field,select,itemOptions,locOptions,download,refreshShared,refreshView:render}))return;
  if(name==='shared-use'){const source=legacyState||state;await api('archive',{state:source});localStorage.setItem('chmltech:WMS_demo:harbor-before-shared-v2',JSON.stringify(source));if(migration==='initialize')await api('initialize',{state:source});localStorage.setItem(MIGRATED,'yes');migration=null;await refreshShared();return;}
  if(name==='shared-replace'){showModal('Replace shared records with this browser copy?',`<p>This browser has ${legacyState.items.length} products and ${legacyState.operations?.purchases?.length||0} POs. Shared storage has ${state.items.length} products and ${state.operations?.purchases?.length||0} POs. Both versions will be backed up. This replaces the entire shared workspace; it does not merge stock balances.</p>`,'Use browser copy',async()=>{await api('archive',{state:legacyState});const result=await api('replace',{state:legacyState,revision:state.revision});localStorage.setItem('chmltech:WMS_demo:harbor-before-shared-v2',JSON.stringify(legacyState));localStorage.setItem(MIGRATED,'yes');state=result.state;$('#modal').close();await refreshShared();});return;}
  if(await documentAction(name,id,el,{s:state,showModal,select,download}))return;
  if(await purchasingAction(name,id,el,{s:state,run,showModal,field,select,itemOptions,locOptions}))return;
  if(await operationAction(name,id,el,{s:state,run,showModal,field,select,itemOptions,locOptions}))return;
  switch(name){
    case 'warehouse-tools':viewMode='classic';recordTab='General';try{localStorage.setItem(VIEW_KEY,viewMode);}catch{}render();if(!['inventory','orders','picking','shipping'].includes(location.hash.slice(1).split('/')[0]))location.hash='inventory';break;
    case 'record-tab':if(['General','Details','Memo','Costing','Custom'].includes(id)){recordTab=id;render();document.getElementById(`fb-tab-${id}`)?.focus();}break;
    case 'nav-group':{const panel=document.getElementById('nav-'+id),expanded=el.getAttribute('aria-expanded')!=='true';el.setAttribute('aria-expanded',String(expanded));panel.hidden=!expanded;navOpen[id]=expanded;try{localStorage.setItem(NAV_KEY,JSON.stringify(navOpen));}catch{}break;}
    case 'menu':document.body.classList.toggle('menu-open');shell(location.hash.slice(1).split('/')[0]||'overview');if(document.body.classList.contains('menu-open'))$('#sidebar .nav-close').focus();else $('#topbar .mobile-menu').focus();break;
    case 'close':$('#modal').close();break;
    case 'help':showModal('Try a complete warehouse workflow','<p>Start with the Insulated travel bottle sample. Each pack contains 3 bottles, each carton contains 12, and each pallet contains 480.</p><ol><li>Open Purchasing and receive the sample purchase order for two cartons: 24 bottles.</li><li>Open the draft sales order for two packs: 6 bottles.</li><li>Issue the order, reserve its stock and finish picking.</li><li>Pack and ship the shipment. The stock balance falls by 6 bottles.</li><li>Edit packaging in Inventory, or use Reset demo to restore the sample warehouse.</li></ol><p><a class="btn primary" href="#orders/order-3">Open the sample sales order</a></p>');break;
    case 'new-order':showModal('New sales order',`${field('Customer','customer','text','','required maxlength="100" placeholder="e.g. Northline Supply"')}${field('Reference (optional)','reference','text','','maxlength="240" placeholder="Customer PO or order note"')}<div class="line-labels"><span>Item</span><span>Quantity</span></div><div id="order-lines">${lineHtml()}</div><button type="button" data-action="add-line" class="btn ghost">${icon('plus')} Add item</button>`,'Create order',(_,form)=>run('createOrder',{customer:form.elements.customer.value,reference:form.elements.reference.value,lines:[...form.querySelectorAll('.order-line')].map(r=>({itemId:r.querySelector('select').value,qty:r.querySelector('input').value}))},rid=>`orders/${rid}`));break;
    case 'add-line':if($('#order-lines').children.length>=50)throw Error('An order supports up to 50 lines.');$('#order-lines').insertAdjacentHTML('beforeend',lineHtml());break;
    case 'remove-line':if($('#order-lines').children.length>1)el.closest('.order-line').remove();else throw Error('Keep at least one order line.');break;
    case 'issue-order':await run('issueOrder',{id});break;
    case 'cancel-order':confirm('Cancel order','Cancel this order and release its outstanding demand? The record will stay in your history.','cancelOrder',{id});break;
    case 'reserve':await run('commitPick',{id});break;
    case 'finish':await run('finishPick',{id},rid=>`shipping/${rid}`);break;
    case 'reverse-pick':showModal('Reverse pick',`<p>Release this reservation and return staged stock to its original location. Reverse any shipment or packing first.</p>${field('Reason (optional)','reason','text','','maxlength="240"')}`,'Reverse pick',data=>run('voidPick',{id,...data}));break;
    case 'pack':showModal('Pack shipment',`<p>Confirm that all order lines are packed. This step does not change inventory.</p>${field('Carrier (optional)','carrier','text',state.shipments.find(sh=>sh.id===id)?.carrier||'','maxlength="240" placeholder="e.g. Local delivery"')}${field('Tracking reference (optional)','tracking','text',state.shipments.find(sh=>sh.id===id)?.tracking||'','maxlength="240"')}`,'Confirm packing',data=>run('packShipment',{id,...data}));break;
    case 'ship':confirm('Ship order','Dispatch all packed quantities? On-hand stock and reservations will be reduced, and the sales order will be fulfilled.','shipShipment',{id});break;
    case 'reverse-shipment':showModal('Reverse shipment / packing',`<p>A shipped order returns to staging with its reservation restored. A packed order returns to Entered without changing stock.</p>${field('Reason (optional)','reason','text','','maxlength="240"')}`,'Confirm reversal',data=>run('voidShipment',{id,...data}));break;
    case 'receive':showModal('Receive stock',`<p>Record an incoming delivery by item, location, and lot. Stock received into storage can be picked immediately.</p>${select('Item','itemId',itemOptions(),id)}<div class="form-grid">${select('Destination','locationId',locOptions(l=>l.type!=='Staging'&&!locationScope(state,l.id).transit&&!locationScope(state,l.id).production),'location-1')}${field('Quantity','qty','number',1,'required min="1" step="1" max="10000000"')}${field('Lot (optional)','lot','text','','maxlength="100" placeholder="UNTRACKED if left blank"')}${field('Delivery note (optional)','note','text','','maxlength="240"')}</div>${receiveExtras(field)}`,'Receive stock',data=>run('receiveStock',{...data,expiresOn:data.expiresOn||undefined}));break;
    case 'move':{const r=state.stock.find(s=>s.id===id),i=itemById(state,r.itemId),scope=locationScope(state,r.locationId);showModal('Move stock',`<p>${e(i.name)} · ${e(r.lot)}<br>From ${e(locationById(state,r.locationId).code)} · ${n(r.qty-r.committed)} ${e(i.uom)} free to move.</p>${select('Destination','locationId',locOptions(l=>l.id!==r.locationId&&l.type!=='Staging'&&sameScope(locationScope(state,l.id),scope)&&!locationScope(state,l.id).transit&&!locationScope(state,l.id).production))}${field('Quantity to move','qty','number',1,`required min="1" step="1" max="${r.qty-r.committed}"`)}${serialField(state,id)}`,'Move stock',data=>run('moveStock',{stockId:id,...data}));break;}
    case 'count':{const r=state.stock.find(s=>s.id===id),i=itemById(state,r.itemId);showModal('Record cycle count',`<p>${e(i.sku)} · ${e(locationById(state,r.locationId).code)} · ${e(r.lot)}<br>${r.committed} reserved. A count cannot reduce stock below this amount.</p>${field('Actual quantity counted','qty','number',r.qty,`required min="${r.committed}" step="1" max="10000000"`)}${field('Reason','reason','text','','required maxlength="240" placeholder="e.g. Monthly cycle count"')}${serialField(state,id)}`,'Save count',data=>run('countStock',{stockId:id,...data}));break;}
    case 'catalog-export':download('chmltech-wms-catalog.csv',exportCatalog(state),'text/csv;charset=utf-8');toast('UTF-8 catalog download started');break;
    case 'catalog-import':$('#catalog-file')._harborCatalogScope=Object.freeze({workspaceId:sharedInfo?.workspace?.id,actor:sharedInfo?.user?.username});$('#catalog-file').value='';$('#catalog-file').click();break;
    case 'edit-item':{const i=itemById(state,id);showModal('Edit product text',field('Item name','name','text',i.name,'required maxlength="100"')+`<label class="field">Product description<textarea name="description" rows="4" maxlength="1000">${e(i.description||'')}</textarea></label>`+field('Preferred supplier','supplier','text',i.supplier||'','maxlength="100"')+field('Category','category','text',i.category,'maxlength="240"'),'Save details',data=>run('saveItemText',{id,...data}));break;}
    case 'new-item':showModal('New inventory item',`<div class="form-grid">${field('SKU','sku','text','','required maxlength="40"')}${field('Item name','name','text','','required maxlength="100"')}${field('Category','category','text','','maxlength="240"')}${field('Preferred supplier','supplier','text','','maxlength="100"')}<label class="field">Product description<textarea name="description" rows="3" maxlength="1000"></textarea></label>${select('Stock unit','uom',[['ea','Each'],['roll','Roll'],['pair','Pair'],['case','Case']])}${field('Reorder point','reorderPoint','number',0,'required min="0" step="1" max="10000000"')}${select('Tracking','tracking',[['Lot','Lot'],['Serial','Serial']])}</div>`,'Create item',data=>run('createItem',data,rid=>`inventory/${rid}`));break;
    case 'new-location':showModal('New location',`${field('Location code','code','text','','required maxlength="20" placeholder="e.g. B-01"')}${field('Name','name','text','','required maxlength="100"')}${select('Location type','type',[['Storage','Storage — available and pickable'],['Receiving','Receiving — available, not pickable'],['Hold','Quality hold — unavailable, not pickable']])}`,'Create location',data=>run('createLocation',data));break;
    case 'location-stock':{const l=locationById(state,id),rows=state.stock.filter(r=>r.locationId===id&&r.qty>0);showModal(`${l.code} · Stock`,rows.length?table(['Item / lot','>On hand','>Reserved'],rows.map(r=>`<tr><td><a class="link" href="#inventory/${r.itemId}">${e(itemById(state,r.itemId).sku)}</a><div class="item-sku">${e(r.lot)}</div></td><td class="num">${n(r.qty)}</td><td class="num">${n(r.committed)}</td></tr>`)):empty('This location is empty','Receive or move stock into this location.'));break;}
    case 'settings':showModal('Data & settings',`<div class="note-box"><p>This demo is saved only in this browser on this device. Other browsers and visitors never see it. There are no automatic backups: download a JSON copy if you want to keep your work.</p></div><div class="data-action"><div><h3>Chinese data & documents / 中文</h3><p>Simplified 简体 and Traditional 繁體 text, UTF-8 catalog CSV and Chinese PDFs. Choose the interface language at the top of the page.</p></div>${btn('Documents / 文档','document-settings','','tiny')}</div><div class="data-action"><div><h3>Product catalog CSV</h3><p>Includes product descriptions and preferred suppliers. Import previews additions and updates; stock quantities stay unchanged. Save files as CSV UTF-8.</p></div>${btn('Export CSV','catalog-export','down','tiny')}${btn('Import CSV','catalog-import','up','tiny')}</div><div class="data-action"><div><h3>Download a backup</h3><p>Inventory, orders, and activity as a JSON file.</p></div>${btn('Export','export','down','tiny')}</div><div class="data-action"><div><h3>Start the demo again</h3><p>Replaces all current data with sample records.</p></div>${btn('Reset demo','reset','rotate','tiny danger')}</div><div class="modal-section"><h3>Browser demo scope</h3><p style="margin:10px 0 0">Warehouse, purchasing, sales, manufacturing and accounting workflows with fictional records. QuickBooks, EDI, carrier, email and payment connections are disconnected. Open a sidebar group to find its modules.</p></div>`);break;
    case 'export':if(!sharedReady)throw Error('The demo is still loading. Try again in a moment.');download(`chmltech-wms-demo-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2));toast('Demo data download started');break;
    case 'import':throw Error("Restoring a backup file is not available in the browser demo. Use Reset demo to start again.");
    case 'reset':document.querySelector('#demo-reset').click();break;case 'disabled-original-reset':showModal('Reset the workspace?',`<p>This replaces all current items, orders, and activity with the sample warehouse. Export a backup first if you want to keep your work.</p>`,'Reset to demo',()=>replaceState(createSeed(new Date().toISOString())));break;
  }
}
document.addEventListener('click',async ev=>{
  const link=ev.target.closest('a[href^="#"]');if(link&&!ev.ctrlKey&&!ev.metaKey&&!ev.shiftKey&&!ev.altKey&&ev.button===0){ev.preventDefault();document.body.classList.remove('menu-open');$('#modal').close();if(link.classList.contains('skip')){$('#main').focus();return;}const target=link.getAttribute('href');if(location.hash!==target)location.hash=target;else{shell(location.hash.slice(1).split('/')[0]);$('#main').focus();}return;}
  const button=ev.target.closest('[data-action]');if(button){ev.preventDefault();try{await action(button.dataset.action,button.dataset.id,button);}catch(err){if($('#modal').open){$('#form-error').textContent=err.message;$('#form-error').classList.add('visible');}else toast(err.message,true);}}
  const f=ev.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();}
});
const searchHandler=createSearchHandler(target=>{const position=target.selectionStart;query=target.value;render();$('#search')?.focus();$('#search')?.setSelectionRange(position,position);});
document.addEventListener('compositionstart',ev=>{if(ev.target.id==='search')searchHandler.start();});
document.addEventListener('compositionend',ev=>{if(ev.target.id==='search')searchHandler.end(ev.target);});
document.addEventListener('input',ev=>{dashboardInput(ev);if(ev.target.id==='search')searchHandler.input(ev);if(ev.target.dataset.maxCharacters){const max=Number(ev.target.dataset.maxCharacters);ev.target.setCustomValidity(charLength(ev.target.value)>max?`Use up to ${max} characters.`:'');}});
document.addEventListener('change',ev=>{
 if(planningChange(ev,state,render))return;
  dashboardModalChange(ev,state);
  if(dashboardChange(ev,render))return;
  purchasingChange(ev,state);
  if(ev.target.id==='view-mode'){
    viewMode=ev.target.value==='harbor'?'harbor':'classic';recordTab='General';query='';filter='All';selectedStock='';
    try{localStorage.setItem(VIEW_KEY,viewMode);}catch{toast('View changed. The browser could not save this preference.',true);}
    render();$('#view-mode').focus();
  }
  if(ev.target.id==='record-filter'){filter=ev.target.value;render();$('#record-filter')?.focus();}
  if(ev.target.dataset.stockId){selectedStock=ev.target.dataset.stockId;render();document.querySelector(`[data-stock-id="${selectedStock}"]`)?.focus();}
});
document.addEventListener('keydown',ev=>{
  if(ev.target.closest('svg [data-action^="dash-"]')&&['Enter',' '].includes(ev.key)){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));return;}
  if(!ev.target.matches('[role="tab"]')||!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;
  ev.preventDefault();const tabs=[...document.querySelectorAll('[role="tab"]:not(:disabled)')],index=tabs.indexOf(ev.target);
  const next=ev.key==='Home'?0:ev.key==='End'?tabs.length-1:(index+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;
  tabs[next]?.click();
});
document.addEventListener('submit',async ev=>{
  if(ev.target.hasAttribute('data-dashboard-dates')){ev.preventDefault();try{dashboardDates(ev.target,render);}catch(err){toast(err.message,true);}return;}
  if(ev.target.id!=='modal-form')return;ev.preventDefault();const form=ev.target,submit=form.querySelector('[type="submit"]');if(!modalSubmit)return;
  if(!beginFormSave(form))return;const handler=modalSubmit;try{await handler(Object.fromEntries(new FormData(form)),form);}catch(err){if(form.isConnected){const box=form.querySelector('#form-error');if(box){box.textContent=err.message;box.classList.add('visible');}}}finally{endFormSave(form);}
});
$('#backup-file').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Backups must be smaller than 5 MB.');const incoming=JSON.parse(decodeUTF8(await file.arrayBuffer()));validateState(incoming);showModal('Restore this backup?',`<p>This backup contains ${incoming.items.length} items, ${incoming.orders.length} orders, and ${incoming.events.length} activity entries. It will replace the current workspace.</p>`,'Replace workspace',()=>replaceState(incoming));}catch(err){toast(`Backup not loaded: ${err.message}`,true);}});
$('#catalog-file').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{
  const scope=ev.target._harborCatalogScope,reviewScope=()=>{if(scope&&(scope.workspaceId!==sharedInfo?.workspace?.id||scope.actor!==sharedInfo?.user?.username))throw Error('The selected company changed. Refresh and review the original company before continuing.');};reviewScope();
  if(file.size>5000000)throw Error('CSV must be smaller than 5 MB.');
  const rows=catalogRows(decodeUTF8(await file.arrayBuffer()));reviewScope();dispatch(state,'importCatalog',{rows});
  const newCount=rows.filter(r=>!state.items.some(i=>i.sku.toUpperCase()===r.sku.trim().toUpperCase())).length;
  showModal('Review catalog import',`<p>${newCount} new items; ${rows.length-newCount} existing items will have their name, description, supplier, category and reorder point updated. Stock, orders and costs stay unchanged.</p><div class="table-scroll"><table><thead><tr><th>SKU</th><th>Name / description</th><th>Supplier</th></tr></thead><tbody>${rows.slice(0,20).map(r=>`<tr><td>${e(r.sku)}</td><td>${e(r.name)}<br>${e(r.description)}</td><td>${e(r.supplier)}</td></tr>`).join('')}</tbody></table></div>${rows.length>20?'<p>Showing the first 20 rows.</p>':''}`,'Import catalog',()=>{reviewScope();return run('importCatalog',{rows});});
 }catch(err){toast(`CSV not loaded: ${err.message}`,true);}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&document.body.classList.contains('menu-open')&&!$('#modal').open){document.body.classList.remove('menu-open');shell(location.hash.slice(1).split('/')[0]);$('#topbar .mobile-menu').focus();}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
// Original browser data is not overwritten during migration.
try{const raw=originalBrowserRaw;legacyState=raw?JSON.parse(raw):null;if(legacyState)validateState(legacyState);}catch{legacyState=null;}
let sessionExpired=false;
const account=mountAccount({onChange:(status,expired)=>{sharedInfo=status;sessionExpired=expired;if(!status.user){sharedReady=false;loadError='';$('#modal').close();}render();},afterSignIn:refreshShared});
render();
startLocalization(()=>state);
startWorkflowControls(()=>({state,info:sharedInfo,ready:sharedReady,hash:location.hash}));
refreshShared().catch(error=>{loadError=error.message;render();});
setInterval(async()=>{if(!sharedReady||document.hidden||$('#modal').open)return;try{const result=await api('workspace');if(result.state&&result.state.revision!==state.revision){state=result.state;render();}}catch(error){sharedReady=false;loadError=error.message;render();}},5000);
window.addEventListener('focus',()=>{if(sharedReady&&!$('#modal').open)refreshShared().catch(()=>{});});



